/* performative-ui legacy package CSS.
   Components are styled in-source with Tailwind utilities and theme tokens.
   Importing `performative-ui-svelte/styles.css` only provides animation
   keyframes; package consumers must compile Tailwind against this package's
   Svelte files and include the performative theme tokens. Prefer the registry
   workflow for production apps. */

@keyframes pui-grad-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes pui-twinkle {
  0%, 100% { opacity: 1; transform: scale(1) rotate(0deg); }
  50% { opacity: 0.6; transform: scale(0.85) rotate(15deg); }
}

@keyframes pui-caret {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

@keyframes pui-spin {
  to { transform: rotate(360deg); }
}

@keyframes pui-pulse-dot {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.4); opacity: 0.6; }
}

@keyframes pui-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(4px); }
}

@keyframes pui-marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes pui-shimmer {
  0% { left: -120%; }
  60%, 100% { left: 120%; }
}

@keyframes pui-aurora-drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  100% { transform: translate3d(-3%, 2%, 0) scale(1.08); }
}

@keyframes pui-breathe {
  0%, 100% { box-shadow: 0 0 0 oklch(0.541 0.251 293 / 0%); }
  50% { box-shadow: 0 0 40px oklch(0.541 0.251 293 / 18%); }
}

@keyframes pui-float-up {
  0% { transform: translateY(20px) rotate(0deg); opacity: 0; }
  10% { opacity: var(--pui-sparkle-peak, 1); }
  100% { transform: translateY(-100vh) rotate(360deg); opacity: 0; }
}

@keyframes pui-wave-shift {
  from { background-position: 0% 50%, 0% 50%, -100% 50%; }
  to { background-position: 0% 50%, 0% 50%, 100% 50%; }
}

/* =============================================================
   prefers-reduced-motion: freeze the library's decorative loops.
   Scoped to [data-slot] elements so consumer markup is untouched.
   Functional indicators (spinners/carets) collapse to a single,
   near-instant iteration rather than disappearing entirely.
   ============================================================= */
@media (prefers-reduced-motion: reduce) {
  [data-slot],
  [data-slot] *,
  [data-slot]::before,
  [data-slot]::after,
  [data-slot] *::before,
  [data-slot] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
